"""Base Resource class for Ansible modules.

Provides common CRUD functionality for all resource modules,
eliminating code duplication across 100+ generated modules.
"""

import re
from typing import Any, Dict, List, Optional, Set, Tuple, Union

from ansible.module_utils.basic import AnsibleModule

from .client import VastClient, select_file_params
from .diff import compute_patch, normalize_resource
from .errors import VastAPIError, VastError, VastNotFoundError
from .schema_overrides import get_overrides, normalize_list_response
from .timeouts import DEFAULT_TASK_TIMEOUT
from .utils.coerce import coerce
from .version import VersionAwareMixin

ResourceId = Union[int, str]


class BaseResource(VersionAwareMixin):
    """Base class for all Ansible module resources.

    Provides common CRUD operations and idempotent lifecycle management.

    Subclasses must define:
    - resource_name: str  # e.g., "alarms", "views"
    - singular: str       # e.g., "alarm", "view"
    - lookup_field: str   # e.g., "name", "path"

    Subclasses may override:
    - async_create: bool = False
    - async_update: bool = False
    - async_delete: bool = False
    - include_ephemeral_in_updates: bool = False  # Set True to allow password updates (breaks idempotency)
    - get(), create(), update(), delete() methods for custom behavior
    """

    resource_name: str = NotImplemented
    singular: str = NotImplemented
    lookup_field: str = "name"

    # Override these for async resources
    async_create: bool = False
    async_update: bool = False
    async_delete: bool = False

    # Override this to include ephemeral fields (passwords/secrets) in update patches
    # This breaks idempotency but allows password updates. Default False for idempotency.
    include_ephemeral_in_updates: bool = False
    can_create: bool = True

    # Set True for endpoints whose PATCH returns a confirmation string (e.g.
    # "apitoken updated") instead of the updated resource object. update() then
    # returns {} and run() rebuilds the result from current state + patch,
    # avoiding both a dict() on the string and a wasteful extra GET.
    update_returns_confirmation: bool = False

    # Multipart file-upload params (Swagger ``in: formData`` ``type: file``).
    # Their values are local file paths, POSTed as multipart/form-data on create.
    # They are write-only: never returned by GET, excluded from the idempotency
    # diff, and never re-uploaded on update (change the file via absent+present).
    file_params: Set[str] = set()

    # Swagger-derived field restrictions (auto-generated by code generator)
    create_only_fields: Set[str] = set()  # Fields only valid during creation (excluded from updates)
    update_only_fields: Set[str] = set()  # Fields only valid during updates (excluded from creates)
    nullable_fields: Set[str] = set()  # Fields a user may explicitly reset to null via the clear_fields param
    delete_query_params: Set[str] = set()
    delete_body_params: Set[str] = set()

    # --- multi-version metadata (auto-generated; see merge_lifecycles) -------
    # {field: {"min": (maj, min), "max": (maj, min) or None}} -- only fields
    # whose availability deviates from the generation floor.
    field_versions: Dict[str, Dict[str, Optional[Tuple[int, int]]]] = {}
    # {(maj, min) boundary: {field: {"request": fn, "response": fn}}}
    field_transforms: Dict[Tuple[int, int], Dict[str, Dict[str, str]]] = {}
    # {field: {"since": (maj,min)|None, "until": (maj,min)|None}} -- the inclusive
    # version range over which the field is required on create.
    required_versions: Dict[str, Dict[str, Optional[Tuple[int, int]]]] = {}

    def __init__(self, module: AnsibleModule):
        """Initialize the resource manager.

        Args:
            module: AnsibleModule instance
        """
        # Shared auth/client/version setup (see VersionAwareMixin).
        self._init_vast_connection(module)

        # Get schema overrides for this resource (version-aware).
        self.overrides = get_overrides(self.resource_name, self.cluster_mm)

    # -- version compatibility & on-wire transforms --------------------------

    def _version_entity(self) -> str:
        return f"Resource '{self.resource_name}'"

    def _field_supported(self, name: str) -> bool:
        """Return True if a field is supported on the current cluster version."""
        info = self.field_versions.get(name)
        if not info or self.cluster_mm is None:
            return True
        fmin = info.get("min")
        fmax = info.get("max")
        if fmin and self.cluster_mm < tuple(fmin):
            return False
        if fmax and self.cluster_mm > tuple(fmax):
            return False
        return True

    def _apply_field_transforms(self, payload: Dict[str, Any], direction: str) -> Dict[str, Any]:
        """Apply version type-coercions to a payload for the current cluster.

        ``direction`` is "request" or "response". Transforms keyed by a boundary
        version apply only when the cluster is OLDER than that boundary (i.e. it
        still speaks the pre-change type).
        """
        if self.cluster_mm is None or not self.field_transforms:
            return payload
        for boundary, fields in self.field_transforms.items():
            if self.cluster_mm >= tuple(boundary):
                continue
            for fname, spec in fields.items():
                if fname in payload:
                    payload[fname] = coerce(payload[fname], spec.get(direction, ""))
        return payload

    def transform_request(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Hook: adapt an outgoing payload to the cluster's VMS version."""
        return self._apply_field_transforms(dict(payload), "request")

    def transform_response(self, data: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        """Hook: adapt an incoming resource dict to the union (newest) schema."""
        if not data:
            return data
        return self._apply_field_transforms(dict(data), "response")

    # -- debug trace helpers -------------------------------------------------

    _MAX_DEBUG_TRACES = 20

    _AUTH_HEADER_RE = re.compile(
        r"(Authorization:\s*(?:Bearer|Basic|Api-Token)\s+)\S+",
        re.IGNORECASE,
    )
    _TOKEN_QUERY_RE = re.compile(
        r"([\?&](?:token|api_key|access_token)=)[^&\s]+",
        re.IGNORECASE,
    )

    def _emit_debug_traces(self) -> None:
        """Emit collected HTTP debug traces as Ansible warnings.

        Uses ``pop_debug_traces()`` so the buffer is cleared after retrieval.
        Only the last ``_MAX_DEBUG_TRACES`` entries are shown; earlier ones are
        noted with a count.
        """
        if not self.client.debug:
            return
        traces = self.client.pop_debug_traces()
        if not traces:
            return
        if len(traces) > self._MAX_DEBUG_TRACES:
            self.module.warn(f"[VAST HTTP] ({len(traces) - self._MAX_DEBUG_TRACES} earlier traces omitted)")
        for trace in traces[-self._MAX_DEBUG_TRACES :]:
            self.module.warn(f"[VAST HTTP] {self._sanitize_trace(trace)}")

    def _sanitize_trace(self, trace: str) -> str:
        """Scrub secrets from a debug trace string."""
        conn = self.client._connection
        for secret in (conn.password, conn.token):
            if secret:
                trace = trace.replace(secret, "***")
        trace = self._AUTH_HEADER_RE.sub(r"\1***", trace)
        trace = self._TOKEN_QUERY_RE.sub(r"\1***", trace)
        return trace

    # -- field helpers -------------------------------------------------------

    def _get_field_value(self, resource: Dict[str, Any], field_name: str) -> Any:
        """Get field value from resource, handling nested objects.

        The API often returns nested objects (e.g., local_provider: {id: 1, name: "default"}),
        but module parameters use flat IDs (e.g., local_provider_id: 1).
        This function handles both cases.
        """
        # Try direct access first
        value = resource.get(field_name)
        if value is not None:
            return value

        # If field ends with _id, try nested object access
        # e.g., local_provider_id -> local_provider.id
        if field_name.endswith("_id"):
            nested_field = field_name[:-3]  # Remove "_id" suffix
            nested_obj = resource.get(nested_field)
            if isinstance(nested_obj, dict):
                return nested_obj.get("id")
            # Handle case where nested object is already an int
            if isinstance(nested_obj, int):
                return nested_obj

        renamed = self.overrides.get("renamed_on_response", {})
        if field_name in renamed:
            return resource.get(renamed[field_name])

        return None

    def _needs_detail_fetch(self, list_result: Dict[str, Any]) -> bool:
        """Check if user wants fields that are missing from list result.

        Compares user's desired state with list endpoint result to determine
        if a detail endpoint fetch is needed to get complete data.

        Args:
            list_result: Resource dict from list endpoint

        Returns:
            True if detail fetch needed, False if list result is sufficient

        Example:
            User wants: {path: "/foo", bucket_logging: {...}}
            List has:   {path: "/foo"}
            Missing:    bucket_logging
            → Returns True (refetch needed)

        Note:
            When ``read_query_params`` is set, detail refetch is skipped by the
            caller because the by-id GET cannot honor those query flags; the
            enriched list row is authoritative.
        """
        if "id" not in list_result:
            return False  # Can't fetch detail without ID

        # Get user's desired state
        desired = self.build_desired_state()
        if not desired:
            return False  # No desired state, list result is fine

        # Check if user wants any fields that list doesn't have
        list_keys = set(list_result.keys())
        desired_keys = set(desired.keys())

        missing_fields = desired_keys - list_keys

        # If user wants fields not in list result, we need detail fetch
        return len(missing_fields) > 0

    def get(
        self,
        lookup_value: Optional[str] = None,
        resource_id: Optional[ResourceId] = None,
        unique_constraints: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        """Get a resource and adapt the response to the union schema.

        Thin version-aware wrapper around :meth:`_get_raw`.
        """
        return self.transform_response(self._get_raw(lookup_value, resource_id, unique_constraints))

    def _get_raw(
        self,
        lookup_value: Optional[str] = None,
        resource_id: Optional[ResourceId] = None,
        unique_constraints: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        """Get resource by lookup field or ID, with optional composite key filtering.

        Args:
            lookup_value: Value of the lookup field (e.g., name="foo")
            resource_id: Optional ID for direct lookup (bypasses lookup field search)
            unique_constraints: Optional dict of fields that together uniquely identify the resource

        Returns:
            Resource dict if found, None otherwise

        Raises:
            VastAPIError: On API errors (except 404/not-found)

        Note: If unique_constraints is provided, multiple matches are filtered to find the exact resource.
        """
        try:
            api = self.client.api[self.resource_name]

            # Direct ID lookup.
            if resource_id is not None:
                return self._get_by_id(api, resource_id)
            if unique_constraints and self.lookup_field not in unique_constraints:
                resource = self._get_by_unique_constraints(api, unique_constraints)
                if resource is not None:
                    return resource

            if lookup_value:
                return self._get_by_lookup_field(api, lookup_value, unique_constraints)

            return None
        except Exception as e:
            raise VastAPIError(
                f"Failed to get {self.singular} (lookup_field={self.lookup_field}, lookup_value={lookup_value}, id={resource_id}): {e}"
            ) from e

    def _get_by_id(self, api: Any, resource_id: ResourceId) -> Optional[Dict[str, Any]]:
        """Fetch a resource by its ID, returning None on a genuine 404.

        When ``read_query_params`` is set, the by-id detail GET (``/<res>/{id}/``)
        cannot honor those flags (e.g. quotas' ``show_user_rules``), so it would
        drop the enriched sub-resources. Resolve via the list endpoint and pick
        the matching id. Filter client-side so a server that ignores ``id=`` as a
        list filter still returns the right row.
        """
        read_query_params = self._read_query_params()
        if read_query_params:
            results = self._process_list_response(api.get(id=resource_id, **read_query_params))
            for row in results:
                if row.get("id") == resource_id:
                    return row
            return None
        try:
            return api[resource_id].first()
        except VastNotFoundError:
            return None

    def _apply_response_filters(self, results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Filter list results by the resource's configured response_filters override."""
        response_filters = self.overrides.get("response_filters", {})
        if not response_filters or not results:
            return results
        return [r for r in results if all(r.get(k) == v for k, v in response_filters.items())]

    def _process_list_response(self, results: List[Any]) -> List[Dict[str, Any]]:
        """Normalize a raw list response, then apply the resource's response filters."""
        return self._apply_response_filters(normalize_list_response(self.overrides, results))

    def _read_query_params(self) -> Dict[str, Any]:
        """Extra query params to attach to list GETs, from the ``read_query_params`` override.

        Some endpoints omit sub-resources unless asked (e.g. quotas echo
        ``user_quotas``/``group_quotas`` only with ``show_user_rules=true``).
        The by-id detail GET does not honor these.
        """
        return dict(self.overrides.get("read_query_params", {}))

    def _get_by_unique_constraints(self, api: Any, unique_constraints: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Look up a resource directly by its unique constraints."""
        results = self._process_list_response(api.get(**unique_constraints, **self._read_query_params()))
        if len(results) > 1:
            self.module.fail_json(msg=(f"Multiple {self.singular} resources found with unique_constraints={unique_constraints}"))
        return results[0] if len(results) == 1 else None

    def _get_by_lookup_field(
        self,
        api: Any,
        lookup_value: str,
        unique_constraints: Optional[Dict[str, Any]],
    ) -> Optional[Dict[str, Any]]:
        """Look up a resource by lookup_field, refining by unique constraints if given."""
        read_query_params = self._read_query_params()
        results = self._process_list_response(api.get(**{self.lookup_field: lookup_value}, **read_query_params))
        if not results:
            return None

        if unique_constraints:
            matches = [r for r in results if all(self._get_field_value(r, k) == v for k, v in unique_constraints.items())]
            if len(matches) > 1:
                self.module.fail_json(
                    msg=(
                        f"Multiple {self.singular} resources found with "
                        f"{self.lookup_field}='{lookup_value}' and unique_constraints={unique_constraints}"
                    )
                )
            if not matches:
                return None
            resource = matches[0]
        else:
            resource = results[0]

        # The by-id detail GET cannot honor read_query_params, so it would drop
        # the enriched sub-resources. The list row is authoritative; skip refetch.
        if read_query_params or not self._needs_detail_fetch(resource):
            return resource
        try:
            return api[resource["id"]].first() or resource
        except VastNotFoundError:
            return resource
        except VastError as e:
            raise VastAPIError(f"Failed to refetch {self.singular} detail (id={resource.get('id')}): {e}") from e

    def _collect_upload_files(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Validate and collect the multipart file-upload params for a create.

        Params listed in ``file_params`` hold local file paths sent as file parts.
        At least one must be supplied (the API rejects a file-less POST). This is
        pure param validation (no I/O), so callers run it outside the request
        ``try`` to surface the typed error without double-wrapping.
        """
        files = select_file_params(self.file_params, payload)
        if not files:
            raise VastAPIError(
                f"Creating a {self.singular} requires at least one file upload "
                f"parameter ({', '.join(sorted(self.file_params))}). None were provided."
            )
        return files

    def create(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """Create a new resource.

        Args:
            payload: Resource data

        Returns:
            Created resource dict

        Raises:
            VastAPIError: On API errors
        """
        payload = self.transform_request(payload)
        # Validate file params before the request try so the typed error is not
        # re-wrapped by the generic handler below.
        files = self._collect_upload_files(payload) if self.file_params else None
        try:
            api = self.client.api[self.resource_name]
            if files is not None:
                fields = {k: v for k, v in payload.items() if k not in self.file_params}
                result = api.post_file(files, **fields)
            else:
                result = api.post(**payload)
        except Exception as e:
            raise VastAPIError(f"Failed to create {self.singular}: {e}") from e

        # Wait for async create if needed
        if self.async_create and self.params.get("wait", True):
            self._wait_for_task(result)
            # Refresh to get actual resource data (not task object)
            if "id" in result and result.get("type") != "async_task":
                refreshed = self.get(resource_id=result["id"])
                if refreshed:
                    return refreshed

        return self.transform_response(result)

    def update(self, resource_id: ResourceId, patch: Dict[str, Any]) -> Dict[str, Any]:
        """Update an existing resource.

        Args:
            resource_id: Resource ID
            patch: Fields to update

        Returns:
            Updated resource dict

        Raises:
            VastAPIError: On API errors
        """
        patch = self.transform_request(patch)
        try:
            api = self.client.api[self.resource_name]
            result = api[resource_id].patch(**patch)
        except Exception as e:
            raise VastAPIError(f"Failed to update {self.singular} {resource_id}: {e}") from e

        # Wait for async update if needed
        if self.async_update and self.params.get("wait", True):
            self._wait_for_task(result)
            # Refresh to get actual resource data (not task object)
            refreshed = self.get(resource_id=resource_id)
            if refreshed:
                return refreshed

        # Endpoints that return a confirmation string carry no resource body to
        # transform. Return an empty dict so run() reconstructs the result from
        # the known current state + patch, avoiding a wasteful extra GET.
        if self.update_returns_confirmation:
            return {}

        return self.transform_response(result)

    def delete(
        self,
        resource_id: ResourceId,
        query_params: Optional[Dict[str, Any]] = None,
        body_params: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Delete a resource.

        Args:
            resource_id: Resource ID

        Returns:
            Delete response (may contain task_id for async)

        Raises:
            VastAPIError: On API errors
        """
        try:
            api = self.client.api[self.resource_name]
            kwargs: Dict[str, Any] = dict(body_params or {})
            if query_params:
                kwargs["_query_params"] = query_params
            result = api[resource_id].delete(**kwargs)
            result = result if result else {}
        except Exception as e:
            raise VastAPIError(f"Failed to delete {self.singular} {resource_id}: {e}") from e

        # Wait for async delete if needed
        if self.async_delete and self.params.get("wait", True):
            self._wait_for_task(result)

        return result

    def _collect_delete_params(self) -> Dict[str, Dict[str, Any]]:
        """Collect user-supplied DELETE-only param values from ``self.params``."""

        def _pick(names: Set[str]) -> Dict[str, Any]:
            return {n: v for n in names for v in [self.params.get(n)] if v is not None}

        return {"query": _pick(self.delete_query_params), "body": _pick(self.delete_body_params)}

    def build_desired_state(self, operation: str = "update", current_state: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Build desired state from module parameters.

        Excludes connection parameters, framework fields, and operation-specific fields.

        Args:
            operation: One of "create" or "update" - determines which fields to include
            current_state: Current resource state (for smart update_only_fields handling)

        Returns:
            Dict of resource fields from module parameters
        """
        # Exclude framework parameters (connection, state, wait, etc.)
        exclude_keys = {
            "vms",  # Connection parameters are nested in this dict
            "id",  # ID is for lookup only, not part of desired state
            "state",
            "wait",
            "wait_timeout",
            "query",
            "clear_fields",
            # Special operation parameters (actions, not resource fields)
            "set_posix_primary",
            "revoke",
            "revoke_access_keys",
        }

        exclude_keys.update(self.delete_query_params)
        exclude_keys.update(self.delete_body_params)

        # Fields whose required-ness is version-bounded must be present when creating
        # against a cluster inside the [since .. until] range (inclusive; None == open).
        if operation == "create" and self.cluster_mm is not None:
            for fname, rng in (self.required_versions or {}).items():
                since = rng.get("since")
                until = rng.get("until")
                in_range = (since is None or self.cluster_mm >= tuple(since)) and (until is None or self.cluster_mm <= tuple(until))
                if in_range and self.params.get(fname) is None:
                    bound = []
                    if since is not None:
                        bound.append(f"since {self._fmt_mm(since)}")
                    if until is not None:
                        bound.append(f"until {self._fmt_mm(until)}")
                    span = f" (required {' '.join(bound)})" if bound else ""
                    self.module.fail_json(msg=(f"Field '{fname}' is required on VMS {self._fmt_mm(self.cluster_mm)}{span}."))

        # Add operation-specific exclusions based on Swagger spec
        if operation == "create":
            # During create, exclude update-only fields (e.g., s3policies.enabled)
            # These fields cannot be set during creation per Swagger spec
            exclude_keys.update(self.update_only_fields)
        elif operation == "update":
            # During update, exclude create-only fields (can't be changed after creation)
            exclude_keys.update(self.create_only_fields)
            # File uploads are write-only and never diffable against the server,
            # so they never participate in a PATCH. Re-uploading a file requires
            # deleting and recreating the resource.
            exclude_keys.update(self.file_params)

        desired = {}
        for key, value in self.params.items():
            if key in exclude_keys or value is None:
                continue
            # Drop fields not supported on the target cluster version so we don't
            # send unknown params to older clusters.
            if not self._field_supported(key):
                self.module.warn(f"Field '{key}' is not supported on VMS {self._fmt_mm(self.cluster_mm)} and will be ignored.")
                continue
            desired[key] = value

        # Explicit null clears: a user-listed field is emitted as None so it is
        # sent to the API to reset the value (only meaningful on update).
        if operation == "update":
            for fname in self._fields_to_clear():
                if fname in exclude_keys or not self._field_supported(fname):
                    continue
                desired[fname] = None

        return desired

    def _fields_to_clear(self) -> Set[str]:
        """Return validated set of fields the user asked to reset to null.

        Restricted to the resource's ``nullable_fields`` (the argument_spec
        ``choices`` already enforce this, but guard here too).
        """
        requested = self.params.get("clear_fields") or []
        return {f for f in requested if f in self.nullable_fields}

    def validate_run_params(self) -> None:
        """Validate parameters before run().

        Ensures we have a way to identify the resource for state=present.
        Subclasses can override for custom validation (e.g. CnodeResource
        relaxes this for loopback clusters).

        Raises:
            VastAPIError: If required parameters are missing.
        """
        state = self.params.get("state", "present")
        lookup_value = self.params.get(self.lookup_field)
        resource_id = self.params.get("id")
        if not lookup_value and not resource_id and state == "present":
            if self.lookup_field == "id":
                required = "'id' parameter is required when state=present"
            else:
                required = f"Either '{self.lookup_field}' or 'id' parameter is required when state=present"
            raise VastAPIError(required)

    def run(self) -> None:
        """Main execution entry point.

        Wraps ``_run_lifecycle()`` so that any ``VastAPIError`` is caught,
        debug traces are emitted (on failure only), and ``fail_json`` is
        called exactly once at the boundary.
        """
        try:
            self._run_lifecycle()
        except VastAPIError as e:
            self._emit_debug_traces()
            self.module.fail_json(msg=str(e))

    def _run_lifecycle(self) -> None:
        """Full CRUD lifecycle -- called by ``run()``.

        All errors raise ``VastAPIError``; the caller handles ``fail_json``.
        """
        # Check for special operation parameters (BaseResource only supports CRUD operations)
        special_ops = {
            "set_posix_primary",
            "revoke",
            "revoke_access_keys",
        }
        active_special_ops = [op for op in special_ops if self.params.get(op)]

        if active_special_ops:
            if self.check_mode:
                self.module.exit_json(
                    changed=True,
                    msg=f"Check mode: Would perform special operation(s): {', '.join(active_special_ops)}",
                    **{self.resource_name: {}},
                )
            raise VastAPIError(
                f"Special operations ({', '.join(active_special_ops)}) require custom module implementation. "
                f"The BaseResource class only supports standard CRUD operations (create, read, update, delete)."
            )

        state = self.params.get("state", "present")
        lookup_value = self.params.get(self.lookup_field)
        resource_id = self.params.get("id")

        self.validate_run_params()

        # Build unique constraints dict from params for composite key lookups
        unique_constraint_fields = self.overrides.get("unique_constraints", set())
        unique_constraints = None
        if unique_constraint_fields:
            unique_constraints = {k: self.params.get(k) for k in unique_constraint_fields if self.params.get(k) is not None}
            if unique_constraints and lookup_value and self.lookup_field in unique_constraint_fields:
                if self.lookup_field not in unique_constraints:
                    unique_constraints[self.lookup_field] = lookup_value

        # Get current state
        current = (
            self.get(lookup_value, resource_id, unique_constraints=unique_constraints) if (lookup_value or resource_id) else None
        )

        changed = False
        result_data = {}
        diff_before = {}
        diff_after = {}

        if state == "absent":
            if current:
                if not self.check_mode:
                    delete_kwargs = self._collect_delete_params()
                    self.delete(
                        current["id"],
                        query_params=delete_kwargs["query"],
                        body_params=delete_kwargs["body"],
                    )
                changed = True
                diff_before = dict(current)
                diff_after = {}
            result_data = current or {}

        else:  # state == present
            desired = self.build_desired_state(operation="create" if not current else "update", current_state=current)

            if not current:
                if not self.can_create:
                    identity = f"id={resource_id}" if resource_id is not None else f"{self.lookup_field}={lookup_value}"
                    raise VastAPIError(
                        f"{self.singular} ({identity}) not found, "
                        f"and this resource cannot be created (no POST endpoint). "
                        f"Verify it refers to an existing resource."
                    )
                # update_only_fields comes from the API schema, but some names
                # overlap Ansible control params. These framework fields are
                # already excluded from the create payload, so treating them
                # as user-supplied update-only values would be noise.
                framework_fields = {"state", "vms", "wait", "wait_timeout", "query"}
                provided_update_only = {
                    f: self.params[f]
                    for f in self.update_only_fields
                    if f not in framework_fields and f in self.params and self.params[f] is not None and self._field_supported(f)
                }
                if not self.check_mode:
                    # Some create endpoints return 201 with no body (e.g.
                    # blobexpansions). Fall back to the desired state so the diff
                    # and returned resource are still populated, mirroring the
                    # update path's `... or {**current, **patch}` guard.
                    result_data = self.create(desired) or dict(desired)
                    result_data = self._apply_update_after_create(result_data, provided_update_only)
                else:
                    result_data = {**desired, **provided_update_only}
                changed = True
                diff_before = {}
                diff_after = dict(result_data)
            else:
                current_normalized = normalize_resource(current, self.overrides, exclude_immutable=True, user_resource=desired)
                desired_normalized = normalize_resource(
                    desired,
                    self.overrides,
                    exclude_immutable=True,
                    include_ephemeral=self.include_ephemeral_in_updates,
                )
                patch = compute_patch(
                    current_normalized,
                    desired_normalized,
                    self.overrides,
                    clear_fields=self._fields_to_clear(),
                )

                if patch:
                    if not self.check_mode:
                        result_data = self.update(current["id"], patch) or {**current, **patch}
                    else:
                        result_data = {**current, **patch}
                    changed = True
                    diff_before = dict(current)
                    diff_after = dict(result_data)
                else:
                    result_data = current

        # Build result
        result = {
            "changed": changed,
            self.resource_name: result_data,
        }
        if changed and (diff_before or diff_after):
            result["diff"] = {"before": diff_before, "after": diff_after}

        self.module.exit_json(**result)

    def _wait_for_task(self, response: Dict[str, Any]) -> None:
        """Wait for an async task to complete.

        Args:
            response: API response that may contain task_id

        Raises:
            VastAPIError: If task fails or times out.
        """
        if response is None:
            return
        task_id = VastClient.extract_task_id(response)
        if task_id:
            try:
                self.client.wait_for_task(task_id, timeout=self.params.get("wait_timeout", DEFAULT_TASK_TIMEOUT))
            except VastAPIError as e:
                raise VastAPIError(f"Async task {task_id} failed: {str(e)}") from e

    def _apply_update_after_create(self, result_data: Dict[str, Any], provided_update_only: Dict[str, Any]) -> Dict[str, Any]:
        """Apply update-only fields after create.

        Args:
            result_data: Result data from create
            provided_update_only: Update-only fields from module parameters

        Returns:
            Result data with update-only fields applied
        """
        if not provided_update_only:
            return result_data

        # Only PATCH values the create didn't already persist; some fields are
        # over-classified as update-only in the schema and the POST honors them.
        to_apply = {k: v for k, v in provided_update_only.items() if result_data.get(k) != v}
        if not to_apply:
            return result_data

        resource_id = result_data.get("id")
        if resource_id is None:
            # Async creates with wait=False return a task object without a
            # resolvable id, so we cannot PATCH here. Warn rather than silently
            # dropping the fields (which would reintroduce the original bug).
            self.module.warn(
                f"Update-only fields {sorted(to_apply)} could not be applied on create "  # nosec B608
                f"because the created resource id is not yet available. "
                f"Run a separate update task to set them."
            )
            return result_data

        try:
            patched = self.update(resource_id, dict(to_apply))
        except VastError as e:
            raise VastAPIError(
                f"{self.singular} (id={resource_id}) was created, but applying "
                f"update-only fields {sorted(to_apply)} failed: {e}"
            ) from e

        if patched:
            return patched
        return {**result_data, **to_apply}
